"""Searchable elemental library pages."""
from pathlib import Path
from html import escape
import json

def library(element):
    data=json.loads((Path(__file__).resolve().parents[1]/'content/library-catalog.json').read_text(encoding='utf-8'))
    names={'fire':('△','Heat, smoke & transformation.'),'water':('▽','Liquid, steam & patience.'),'earth':('◇','Stone, clay & tradition.'),'air':('≋','Lift, flow & lightness.')}
    symbol,subtitle=names[element]
    nav=''.join(f'<a href="/{e}/" '+('aria-current="page"' if e==element else '')+f'>{e.title()}</a>' for e in names)
    fallback=''.join(f'<li><a href="{escape(r["url"])}" target="_blank" rel="noopener noreferrer">{escape(r["title"])} · {escape(r["publisher"])}</a></li>' for r in data['resources'] if element in r['elements'])
    return f'''<div class="element-library" data-element="{element}"><section class="wrap library-intro"><nav class="element-tabs" aria-label="Element libraries">{nav}</nav><div class="library-title"><span aria-hidden="true">{symbol}</span><div><p class="eyebrow">THE ELEMENTAL LIBRARY</p><h1>{element.title()}</h1></div></div><p class="lead">{subtitle}</p><p class="library-description">A growing collection of articles, guides, and ideas. Browse the feed or search by cooking method, tool, title, or publisher.</p></section><section class="wrap library-resources section" id="resources" aria-labelledby="resource-heading"><p class="eyebrow">READ / WATCH / LEARN</p><h2 id="resource-heading" tabindex="-1">Related resources.</h2><p id="selected-method-note" class="selected-method-note"></p><details class="library-discovery"><summary>Search &amp; filter <span>Find an article or refine these resources</span></summary><form class="library-controls" role="search" id="library-search"><div class="library-query"><label for="resource-query">Search titles, publishers, methods, or tools</label><input id="resource-query" type="search" placeholder="Find something you remember…" maxlength="200"></div><div><label for="resource-kind">Format</label><select id="resource-kind"><option value="">All formats</option><option>Guide</option><option>Article</option><option>Recipe</option><option>Reference</option><option>Video library</option></select></div><div><label for="resource-sort">Sort</label><select id="resource-sort"><option value="newest">Newest published</option><option value="added">Recently added</option><option value="oldest">Oldest published</option><option value="title">Title A–Z</option></select></div><button class="underlink" type="reset">Clear filters</button></form></details><p id="library-status" class="library-status" role="status" aria-live="polite">Loading the resource collection…</p><div id="resource-grid" class="resource-grid"></div><button id="resource-more" class="button" type="button" hidden>Show more resources</button><div class="library-source-notes" id="library-sources"></div><p class="small muted">Articles open on their publishers’ websites. The archive keeps collected links searchable; original pages may change or be removed. RSS tags are assigned automatically and may be broad.</p><noscript><ul>{fallback}</ul><p>Enable JavaScript to search and sort the complete collection.</p></noscript></section></div>'''
